88	    private String submit(long windowId, String userId, String amount, String actor) throws Exception {
89	        String allocationKey = key("ak");
90	        Map<String, Object> body = new HashMap<>();
91	        body.put("commandKey", key("ac"));
92	        body.put("allocationKey", allocationKey);
93	        body.put("windowId", windowId);
94	        body.put("userId", userId);
95	        body.put("amount", amount);
96	        postOk("/api/allocations", body, actor);
