        // 持有额度扣减为 2.000，仍 APPROVED
        assertEquals("2", allocation(windowId, a).get("heldAmount").asText());
        // 再核销 2 -> 持有 0 仍 APPROVED；继续核销 -> 422 INSUFFICIENT_BALANCE，账目不变
        settleOk(a, key("sk"), "2", "alice");
