    ChannelRow channel = repository.lockChannel(channelId);
    if (channel == null) {
        throw ApiException.notFound("CHANNEL_NOT_FOUND", "渠道不存在: " + channelId);
    }
    // outageKey 业务键重放：同键同指纹（渠道、时段、规范化受影响集合）返回首次结果
